'use client'

import * as React from 'react'
import { DropdownMenu } from 'radix-ui'
import { Check, NavArrowDown, Plus } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { Button } from '@/registry/satin/ui/button'
import type { BadgeTone } from '@/registry/satin/ui/badge'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * AgentPicker, from the uiKit Agent picker docs view (3890:47473): a rounded Button with the
 * current agent's avatar, name and a chevron, opening a menu of agents. Menu rows are 1:1
 * with `DropdownMenu/Item` (653:19165): 8px side padding, radius-lg, medium 13/13 label and a
 * 13px text/muted description 4px under it (`layout=stacked`, 20px avatar), or the label alone
 * (`layout=inline`, 16px avatar) when `showDescription` is off. Hover and the selected row
 * fill bg/selected; the selected row also shows a check in status/green, so selection never
 * relies on colour alone. The menu is bg/popover, a border/subtle hairline, radius-xl, 4px
 * padding, 255 wide, with the shadcn sm shadow.
 *
 * Built on Radix DropdownMenu (radio group semantics, arrow keys, typeahead, Escape).
 * The avatar is a small local one on the Badge hue pairs, so this file has no dependency
 * on a separate Avatar component.
 */

export type Agent = {
  id: string
  name: string
  /** One line on what the agent does. */
  description?: string
  /** Two letters for the avatar; taken from the name when left out. */
  initials?: string
  /** Avatar hue, same pairs as Badge. */
  tone?: BadgeTone
  /** Initials on the tone, or the flappy bird painted in it. */
  avatar?: 'initials' | 'flappy'
}

export interface AgentPickerProps {
  agents: Agent[]
  /** The selected agent's id. */
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  /** Show the one-line description under each name. Turn it off once agents are familiar. */
  showDescription?: boolean
  /** Secondary under the composer, Tertiary inside dense toolbars. */
  variant?: 'secondary' | 'tertiary'
  /** md is the 28px trigger, xs the 24px one. */
  size?: 'md' | 'xs'
  /** Adds a "New agent" action under the list. */
  onCreate?: () => void
  /** Label for the create action. */
  createLabel?: string
  /** Shown on the trigger when nothing is selected. */
  placeholder?: string
  /** Controlled open state, e.g. to show the menu open on a docs stage. */
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Render the menu in place instead of in a portal. */
  disablePortal?: boolean
  className?: string
}

export function AgentPicker({
  agents,
  value: valueProp,
  defaultValue,
  onValueChange,
  showDescription = true,
  variant = 'secondary',
  size = 'md',
  onCreate,
  createLabel = 'New agent',
  placeholder = 'Choose an agent',
  open,
  defaultOpen,
  onOpenChange,
  disablePortal = false,
  className,
}: AgentPickerProps) {
  const labels = useSatinLabels()
  const [inner, setInner] = React.useState(defaultValue ?? agents[0]?.id)
  const value = valueProp ?? inner
  const current = agents.find((a) => a.id === value)

  const select = (id: string) => {
    setInner(id)
    onValueChange?.(id)
  }

  const content = (
    <AgentMenu
      agents={agents}
      value={value}
      onValueChange={select}
      showDescription={showDescription}
      onCreate={onCreate}
      createLabel={createLabel}
    />
  )

  return (
    <DropdownMenu.Root open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange} modal={false}>
      <DropdownMenu.Trigger asChild>
        <Button
          variant={variant}
          size={size}
          shape="rounded"
          className={cn('sa:data-[state=open]:bg-action-secondary-bg-hover', className)}
        >
          {current && <AgentAvatar agent={current} size={16} />}
          <span className="sa:truncate">
            {current && <span className="sa:sr-only">{labels.agent}: </span>}
            {current ? current.name : placeholder}
          </span>
          <NavArrowDown aria-hidden data-chevron />
        </Button>
      </DropdownMenu.Trigger>
      {disablePortal ? content : <DropdownMenu.Portal>{content}</DropdownMenu.Portal>}
    </DropdownMenu.Root>
  )
}

function AgentMenu({
  agents,
  value,
  onValueChange,
  showDescription,
  onCreate,
  createLabel,
}: {
  agents: Agent[]
  value?: string
  onValueChange: (id: string) => void
  showDescription: boolean
  onCreate?: () => void
  createLabel: string
}) {
  return (
    <DropdownMenu.Content
      align="start"
      sideOffset={8}
      className={cn(
        'sa:z-50 sa:flex sa:w-[255px] sa:max-w-[520px] sa:flex-col sa:gap-1 sa:rounded-xl sa:border sa:border-border-subtle sa:bg-bg-popover sa:p-1 sa:outline-none',
        'sa:[box-shadow:0_1px_3px_0_var(--effect-shadow-sm),0_1px_2px_-1px_var(--effect-shadow-sm)]',
        'sa:data-[state=open]:[animation:satin-enter_var(--sa-duration-fast)_var(--sa-ease-out)]',
      )}
    >
      <DropdownMenu.RadioGroup value={value} onValueChange={onValueChange} className="sa:flex sa:flex-col">
        {agents.map((agent) => (
          <AgentMenuItem key={agent.id} agent={agent} showDescription={showDescription} />
        ))}
      </DropdownMenu.RadioGroup>
      {onCreate && (
        <DropdownMenu.Item
          onSelect={onCreate}
          className={cn(
            'sa:flex sa:h-control-height-xs sa:items-center sa:gap-1 sa:self-start sa:rounded-md sa:px-2 sa:text-sm sa:font-medium sa:text-text-default sa:outline-none sa:select-none',
            'sa:transition-[background-color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
            'sa:[&_svg]:size-icon-size-sm sa:[&_svg]:text-text-muted sa:[&_svg]:[stroke-width:1.875]',
            'sa:data-highlighted:bg-bg-hover',
          )}
        >
          <Plus aria-hidden />
          {createLabel}
        </DropdownMenu.Item>
      )}
    </DropdownMenu.Content>
  )
}

export interface AgentMenuItemProps
  extends Omit<React.ComponentProps<typeof DropdownMenu.RadioItem>, 'value' | 'children'> {
  agent: Agent
  showDescription?: boolean
  'data-force'?: 'hover'
}

/** One row of the menu, `DropdownMenu/Item` (653:19165). Must sit inside the picker's radio group. */
export function AgentMenuItem({ agent, showDescription = true, className, ...props }: AgentMenuItemProps) {
  const stacked = showDescription && !!agent.description
  return (
    <DropdownMenu.RadioItem
      value={agent.id}
      className={cn(agentRowClass, className)}
      {...props}
    >
      <AgentAvatar agent={agent} size={stacked ? 20 : 16} />
      <AgentRowText agent={agent} stacked={stacked} />
      <DropdownMenu.ItemIndicator className="sa:flex sa:shrink-0">
        <Check aria-hidden className="sa:size-icon-size sa:text-status-green-fg sa:[stroke-width:1.875]" />
      </DropdownMenu.ItemIndicator>
    </DropdownMenu.RadioItem>
  )
}

const agentRowClass = cn(
  'sa:flex sa:min-h-8 sa:w-full sa:items-center sa:gap-2 sa:rounded-lg sa:px-2 sa:py-1.5 sa:text-left sa:outline-none sa:select-none',
  'sa:transition-[background-color] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
  'sa:data-highlighted:bg-bg-selected sa:data-[force=hover]:bg-bg-selected sa:data-[state=checked]:bg-bg-selected',
)

function AgentRowText({ agent, stacked }: { agent: Agent; stacked: boolean }) {
  return (
    <span className="sa:flex sa:min-w-0 sa:flex-1 sa:flex-col sa:justify-center sa:gap-1">
      <span className="sa:text-sm sa:leading-[13px] sa:font-medium sa:text-text-default">{agent.name}</span>
      {stacked && <span className="sa:text-sm sa:font-normal sa:text-text-muted">{agent.description}</span>}
    </span>
  )
}

/**
 * A static menu row for state sheets and docs (no menu around it): the same look as a menu
 * item, with `state` forced to default, hover or selected.
 */
export function AgentPickerRow({
  agent,
  state = 'default',
  showDescription = true,
  className,
}: {
  agent: Agent
  state?: 'default' | 'hover' | 'selected'
  showDescription?: boolean
  className?: string
}) {
  const stacked = showDescription && !!agent.description
  return (
    <div
      data-force={state === 'hover' ? 'hover' : undefined}
      data-state={state === 'selected' ? 'checked' : undefined}
      className={cn(agentRowClass, className)}
    >
      <AgentAvatar agent={agent} size={stacked ? 20 : 16} />
      <AgentRowText agent={agent} stacked={stacked} />
      {state === 'selected' && (
        <Check aria-hidden className="sa:size-icon-size sa:shrink-0 sa:text-status-green-fg sa:[stroke-width:1.875]" />
      )}
    </div>
  )
}

/**
 * Initials on a Badge hue pair, round. 16px uses semibold 7/8, 20px semibold 9/10, as on
 * the uiKit Avatar (992:20199). These sizes have no type token, so they stay raw.
 * `avatar="flappy"` draws the flappy bird instead, in the agent's tone.
 */
export function AgentAvatar({ agent, size = 16 }: { agent: Agent; size?: 16 | 20 }) {
  if (agent.avatar === 'flappy') return <FlappyAvatar tone={agent.tone ?? 'brand'} size={size} />
  const initials = agent.initials ?? toInitials(agent.name)
  return (
    <span
      aria-hidden
      data-tone={agent.tone ?? 'brand'}
      className={cn(
        'sa:inline-flex sa:shrink-0 sa:items-center sa:justify-center sa:rounded-full sa:bg-tone-bg sa:font-semibold sa:tracking-normal sa:text-tone-fg',
        size === 16 ? 'sa:size-4 sa:text-[7px] sa:leading-2' : 'sa:size-5 sa:text-[9px] sa:leading-[10px]',
      )}
    >
      {initials}
    </span>
  )
}

/**
 * The flappy bird (uiKit flappyAgent, 1215:69019) as a 17 × 12 pixel grid: 0 outline, 1 body,
 * 2 eye and wing, 3 beak, 4 belly. Body and belly take the tone's hue at a fixed, bright
 * lightness (0.8 and 0.68 in OKLCH, chroma up a third), so each agent gets its own bird on the
 * Badge hues and it stays as vivid as the original yellow one in both themes.
 */
const FLAPPY_GRID = [
  '......000000.....',
  '....001111020....',
  '...01111102220...',
  '.00001111022020..',
  '022220111022020..',
  '022222011102220..',
  '0122210111100000.',
  '.0111011110333330',
  '..00044440300000.',
  '....044444033330.',
  '.....00444400000.',
  '.......0000......',
]
const FLAPPY_FILL = [
  '#000',
  'oklch(from var(--tone-fg) 0.8 calc(c * 1.33) h)',
  '#fff',
  '#ff5722',
  'oklch(from var(--tone-fg) 0.68 calc(c * 1.33) h)',
]

function FlappyAvatar({ tone, size }: { tone: BadgeTone; size: 16 | 20 }) {
  return (
    <svg
      aria-hidden
      data-tone={tone}
      width={size}
      height={size}
      viewBox="0 -2.5 17 17"
      shapeRendering="crispEdges"
      className="sa:shrink-0"
    >
      {FLAPPY_GRID.flatMap((row, y) =>
        [...row].map((c, x) => (c === '.' ? null : <rect key={`${x}-${y}`} x={x} y={y} width={1} height={1} fill={FLAPPY_FILL[+c]} />)),
      )}
    </svg>
  )
}

function toInitials(name: string) {
  const words = name.trim().split(/\s+/)
  const letters = words.length > 1 ? words[0][0] + words[1][0] : name.slice(0, 2)
  return letters.toUpperCase()
}
